const App = () => {
  const [view, setView] = useState('home'); // home, certificate, admin
  const [name, setName] = useState('');
  const [loading, setLoading] = useState(false);
  const [registrations, setRegistrations] = useState([]);
  
  // Admin State
  const [adminEmail, setAdminEmail] = useState('');
  const [adminPass, setAdminPass] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);
  
  // Website Customization State
  const [headerLogo, setHeaderLogo] = useState(null);

  // Load data & settings on init
  useEffect(() => {
    try {
      const savedData = localStorage.getItem('iskcon_parivartan_data');
      if (savedData) {
        setRegistrations(JSON.parse(savedData));
      }
      
      const savedConfig = localStorage.getItem('iskcon_config');
      if (savedConfig) {
        const config = JSON.parse(savedConfig);
        if (config.headerLogo) setHeaderLogo(config.headerLogo);
      }
    } catch (e) {
      console.error("Storage error", e);
    }
  }, []);

  const handleGenerate = (e) => {
    e.preventDefault();
    if (!name.trim()) return;

    setLoading(true);
    
    // Simulate processing
    setTimeout(() => {
      const newEntry = {
        id: Date.now(),
        name: name.trim(),
        date: new Date().toLocaleDateString(),
        timestamp: new Date().toISOString()
      };

      const updatedList = [...registrations, newEntry];
      setRegistrations(updatedList);
      localStorage.setItem('iskcon_parivartan_data', JSON.stringify(updatedList));
      
      setView('certificate');
      setLoading(false);
    }, 800);
  };

  const handleAdminLogin = (e) => {
    e.preventDefault();
    if (adminEmail === 'shivesh211204@gmail.com' && adminPass === 'GudiyA@123') {
      setIsAdmin(true);
      setAdminEmail('');
      setAdminPass('');
    } else {
      alert('Incorrect Credentials');
    }
  };

  const handleHeaderLogoUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64 = reader.result;
        setHeaderLogo(base64);
        const currentConfig = JSON.parse(localStorage.getItem('iskcon_config') || '{}');
        localStorage.setItem('iskcon_config', JSON.stringify({ ...currentConfig, headerLogo: base64 }));
      };
      reader.readAsDataURL(file);
    }
  };

  const downloadCSV = () => {
    const headers = ['ID,Name,Date,Timestamp'];
    const rows = registrations.map(r => `${r.id},"${r.name}",${r.date},${r.timestamp}`);
    const csvContent = "data:text/csv;charset=utf-8," + [headers, ...rows].join("\n");
    const encodedUri = encodeURI(csvContent);
    const link = document.createElement("a");
    link.setAttribute("href", encodedUri);
    link.setAttribute("download", "parivartan_participants.csv");
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="min-h-screen bg-orange-50 font-sans text-gray-800 selection:bg-orange-200">
      
      {/* Navigation / Header */}
      <nav className="bg-gradient-to-r from-orange-600 to-amber-600 text-white shadow-lg p-4 sticky top-0 z-50">
        <div className="max-w-4xl mx-auto flex justify-between items-center">
          <div className="flex items-center gap-3">
             {/* Dynamic Web Header Logo */}
             {headerLogo ? (
               <img src={headerLogo} alt="Logo" className="w-12 h-12 object-contain bg-white/10 rounded p-1" />
             ) : (
               // Default Yellowish Logo
               <svg className="w-10 h-10 fill-current text-yellow-200" viewBox="0 0 24 24">
                 <path d="M12 2.5c0 0-4 6-5 9 1 3 5 5 5 5s4-2 5-5c-1-3-5-9-5-9z" opacity="0.9"/>
                 <path d="M12 22c0 0-9-3-9-8 0-4 6-8 9-8 3 0 9 4 9 8 0 5-9 8-9 8z"/>
               </svg>
             )}
            <div>
              <h1 className="font-bold text-lg leading-tight">ISKCON Ujjain</h1>
              <p className="text-xs text-orange-100 opacity-90">International Society for Krishna Consciousness</p>
            </div>
          </div>
          <button 
            onClick={() => setView(view === 'admin' ? 'home' : 'admin')}
            className="text-xs bg-black/20 hover:bg-black/30 px-3 py-1 rounded transition"
          >
            {view === 'admin' ? 'Back to Home' : 'Admin'}
          </button>
        </div>
      </nav>

      <main className="max-w-4xl mx-auto p-4 md:p-8">
        
        {view === 'home' && (
          <div className="max-w-md mx-auto bg-white rounded-2xl shadow-xl overflow-hidden border border-orange-100 transform transition hover:shadow-2xl">
            <div className="bg-[url('https://www.transparenttextures.com/patterns/cream-paper.png')] bg-orange-100 p-8 text-center border-b border-orange-200 relative overflow-hidden">
               <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-b from-orange-200/50 to-transparent pointer-events-none"></div>
               
              <h2 className="text-4xl font-extrabold text-orange-800 mb-2 relative z-10 drop-shadow-sm">Parivartan Camp</h2>
              <p className="text-orange-900 font-semibold relative z-10">Life Transformation Workshop</p>
              <div className="mt-4 inline-block bg-white px-4 py-1 rounded-full text-sm text-orange-600 font-bold shadow-sm relative z-10 border border-orange-200">
                16-18 January • ISKCON Auditorium
              </div>
            </div>
            
            <div className="p-8">
              <form onSubmit={handleGenerate} className="space-y-6">
                <div>
                  <label className="block text-sm font-bold text-gray-700 mb-2 uppercase tracking-wide">Participant Name</label>
                  <div className="relative group">
                    <User className="absolute left-3 top-3 text-gray-400 w-5 h-5 group-focus-within:text-orange-500 transition-colors" />
                    <input 
                      type="text"
                      required
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-lg focus:ring-0 focus:border-orange-500 outline-none transition font-medium text-lg"
                      placeholder="e.g., Rahul Sharma"
                    />
                  </div>
                  <p className="text-xs text-gray-500 mt-2 ml-1">
                    *This name will appear on your official certificate.
                  </p>
                </div>

                <button 
                  type="submit"
                  disabled={loading}
                  className="w-full bg-gradient-to-r from-orange-600 to-red-600 hover:from-orange-700 hover:to-red-700 text-white font-bold py-4 rounded-lg shadow-lg hover:shadow-xl transform hover:-translate-y-1 transition-all disabled:opacity-70 disabled:cursor-not-allowed flex justify-center items-center gap-2 text-lg"
                >
                  {loading ? 'Generating Certificate...' : (
                    <>
                      <span>Get Certificate</span>
                      <CheckCircle className="w-6 h-6" />
                    </>
                  )}
                </button>
              </form>
            </div>
          </div>
        )}

        {view === 'certificate' && (
          <div className="flex flex-col items-center animate-fade-in">
             <button 
                onClick={() => { setView('home'); setName(''); }}
                className="self-start mb-6 text-gray-500 hover:text-orange-600 flex items-center gap-2 transition font-medium px-4 py-2 hover:bg-white rounded-lg"
              >
                <ArrowLeft className="w-4 h-4" /> Generate Another
              </button>

            <div className="bg-white p-2 rounded-lg shadow-2xl mb-8 max-w-full overflow-hidden border border-gray-100">
              <CertificateCanvas userName={name} />
            </div>

            <div className="text-center max-w-lg">
              <h3 className="text-3xl font-bold text-gray-800 mb-2">Hare Krishna, {name}!</h3>
              <p className="text-gray-600 mb-6">Your certificate is ready. Download it below and share your achievement!</p>
            </div>
          </div>
        )}

        {view === 'admin' && (
          <div className="bg-white rounded-xl shadow-lg border border-gray-200 overflow-hidden">
            <div className="bg-gray-800 text-white p-6 flex justify-between items-center">
              <h2 className="text-xl font-bold flex items-center gap-2">
                <ShieldCheck className="w-6 h-6 text-green-400" />
                Admin Dashboard
              </h2>
              {isAdmin && (
                  <button onClick={() => setIsAdmin(false)} className="text-gray-300 hover:text-white" title="Logout">
                      <LogOut className="w-5 h-5"/>
                  </button>
              )}
            </div>

            {!isAdmin ? (
              <div className="p-8 max-w-sm mx-auto text-center">
                <p className="mb-4 text-gray-600">Enter admin credentials to access data.</p>
                <form onSubmit={handleAdminLogin} className="space-y-4">
                  <input 
                    type="email" 
                    placeholder="Email"
                    value={adminEmail}
                    onChange={(e) => setAdminEmail(e.target.value)}
                    className="w-full px-4 py-2 border rounded focus:ring-2 focus:ring-gray-500 outline-none"
                  />
                  <input 
                    type="password" 
                    placeholder="Password"
                    value={adminPass}
                    onChange={(e) => setAdminPass(e.target.value)}
                    className="w-full px-4 py-2 border rounded focus:ring-2 focus:ring-gray-500 outline-none"
                  />
                  <button className="w-full bg-gray-800 text-white py-2 rounded hover:bg-gray-700 transition">
                    Login
                  </button>
                </form>
              </div>
            ) : (
              <div className="p-6 space-y-8">
                <div className="bg-gray-50 p-6 rounded-lg border border-gray-200">
                    <h3 className="text-lg font-semibold flex items-center gap-2 mb-4 text-gray-800">
                        <Settings className="w-5 h-5" /> Website Customization
                    </h3>
                    <div className="flex items-center gap-6">
                        <div className="w-24 h-24 bg-gradient-to-r from-orange-600 to-amber-600 rounded-lg flex items-center justify-center overflow-hidden shadow-inner">
                            {headerLogo ? <img src={headerLogo} alt="Preview" className="w-16 h-16 object-contain"/> : <span className="text-xs text-white opacity-50">No Logo</span>}
                        </div>
                        <div className="flex-1">
                            <label className="block text-sm font-medium text-gray-700 mb-2">Change Header Logo</label>
                            <div className="flex gap-3">
                                <label className="cursor-pointer bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg flex items-center gap-2 transition shadow-sm">
                                    <Upload className="w-4 h-4" /> Upload Image
                                    <input type="file" accept="image/*" className="hidden" onChange={handleHeaderLogoUpload} />
                                </label>
                                {headerLogo && (
                                    <button onClick={() => { setHeaderLogo(null); localStorage.removeItem('iskcon_config'); }} className="text-red-500 hover:text-red-700 text-sm font-medium px-2">
                                        Reset to Default
                                    </button>
                                )}
                            </div>
                            <p className="text-xs text-gray-500 mt-2">Upload the main logo for the top navigation bar. (PNG/SVG recommended)</p>
                        </div>
                    </div>
                </div>

                <div>
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-lg font-semibold text-gray-800">Registered Participants</h3>
                        <div className="flex gap-4 items-center">
                            <span className="text-sm text-gray-500">Total: {registrations.length}</span>
                            <button 
                                onClick={downloadCSV}
                                className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded flex items-center gap-2 transition"
                            >
                                <Download className="w-4 h-4" /> Download CSV
                            </button>
                        </div>
                    </div>

                    <div className="overflow-x-auto border rounded-lg max-h-96">
                    <table className="w-full text-left text-sm">
                        <thead className="bg-gray-100 sticky top-0">
                        <tr>
                            <th className="px-4 py-3 font-semibold text-gray-700">ID</th>
                            <th className="px-4 py-3 font-semibold text-gray-700">Name</th>
                            <th className="px-4 py-3 font-semibold text-gray-700">Date Generated</th>
                        </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-100 bg-white">
                        {registrations.length === 0 ? (
                            <tr>
                            <td colSpan="3" className="px-4 py-8 text-center text-gray-500">No records found yet.</td>
                            </tr>
                        ) : (
                            registrations.slice().reverse().map((reg) => (
                            <tr key={reg.id} className="hover:bg-gray-50">
                                <td className="px-4 py-3 text-gray-500 font-mono text-xs">{reg.id}</td>
                                <td className="px-4 py-3 font-medium text-gray-800">{reg.name}</td>
                                <td className="px-4 py-3 text-gray-500">{reg.timestamp ? new Date(reg.timestamp).toLocaleString() : reg.date}</td>
                            </tr>
                            ))
                        )}
                        </tbody>
                    </table>
                    </div>
                </div>
              </div>
            )}
          </div>
        )}
      </main>

      <footer className="mt-12 py-6 text-center text-gray-500 text-sm border-t border-gray-200 bg-white">
        <p>© 2026 ISKCON Ujjain. All rights reserved.</p>
        <p className="mt-1 text-xs">Developed for Parivartan Camp</p>
      </footer>
    </div>
  );
};

const CertificateCanvas = ({ userName }) => {
  const canvasRef = useRef(null);
  const [logoImage, setLogoImage] = useState(null);
  const [logoError, setLogoError] = useState(false);

  // Load the logo image once
  useEffect(() => {
    const img = new Image();
    img.src = ISKCON_LOGO_SVG;
    img.onload = () => setLogoImage(img);
    img.onerror = (e) => {
        console.error("Logo failed to load", e);
        setLogoError(true);
    }
  }, []);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    
    // High Res Portrait A4
    const width = 800;
    const height = 1130;
    canvas.width = width;
    canvas.height = height;

    // --- 1. Background ---
    const gradient = ctx.createLinearGradient(0, 0, 0, height);
    gradient.addColorStop(0, '#fffdf5'); 
    gradient.addColorStop(0.5, '#fff7ed'); 
    gradient.addColorStop(1, '#ffedd5'); 
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);

    // --- 2. Borders ---
    const borderPadding = 30;
    const innerBorder = 45;
    ctx.strokeStyle = '#c2410c'; 
    ctx.lineWidth = 10;
    ctx.strokeRect(borderPadding, borderPadding, width - borderPadding*2, height - borderPadding*2);
    ctx.strokeStyle = '#facc15'; 
    ctx.lineWidth = 3;
    ctx.strokeRect(innerBorder, innerBorder, width - innerBorder*2, height - innerBorder*2);

    // --- 3. Draw Watermark (Behind Text) ---
    if (logoImage) {
        ctx.save();
        ctx.globalAlpha = 0.04; 
        const wmWidth = 400;
        // Maintain aspect ratio from original 528x472
        const wmHeight = (wmWidth / 528) * 472; 
        ctx.drawImage(logoImage, (width - wmWidth)/2, (height - wmHeight)/2 + 50, wmWidth, wmHeight);
        ctx.restore();
    }


    // --- 4. Header Text (Hindi) ---
    ctx.textAlign = 'center';
    
    // Hindi Title (Top)
    const topMargin = 85;
    ctx.font = 'bold 24px serif';
    ctx.fillStyle = '#9a3412';
    ctx.fillText('अंतर्राष्ट्रीय कृष्ण भावनामृत संघ (इस्कॉन)', width / 2, topMargin);

    // Hindi Founder (Sub-Top)
    ctx.font = 'bold 14px serif';
    ctx.fillStyle = '#7c2d12';
    ctx.fillText('संस्थापक आचार्य: कृष्णकृपामूर्ति श्री श्रीमद् ए.सी. भक्तिवेदान्त स्वामी प्रभुपाद', width / 2, topMargin + 25);


    // A. Draw the Loaded SVG Logo
    const logoY = topMargin + 40; // Reduced margin from text
    let logoHeightDrawn = 0; 

    if (logoImage) {
        ctx.save();
        // Target size on canvas: 200px width (increased size)
        const targetW = 200; 
        const targetH = (targetW / 528) * 472; 
        logoHeightDrawn = targetH;
        
        const logoX = (width - targetW) / 2;
        
        ctx.drawImage(logoImage, logoX, logoY, targetW, targetH);
        ctx.restore();
    } else if (logoError) {
        ctx.save();
        ctx.font = 'bold 24px serif';
        ctx.fillStyle = '#9a3412';
        ctx.textAlign = 'center';
        ctx.fillText("ISKCON LOGO", width/2, logoY + 80);
        ctx.restore();
        logoHeightDrawn = 100; 
    } else {
        ctx.save();
        ctx.font = '20px sans-serif';
        ctx.fillStyle = '#aaa';
        ctx.textAlign = 'center';
        ctx.fillText("Loading Logo...", width/2, logoY + 80);
        ctx.restore();
        logoHeightDrawn = 100;
    }

    // ISKCON UJJAIN Text (Below Logo) - TIGHT spacing
    const ujjainTextY = logoY + logoHeightDrawn + 5; // Very tight margin (5px)
    
    ctx.font = 'bold 28px serif';
    ctx.fillStyle = '#9a3412'; 
    ctx.fillText('ISKCON UJJAIN', width / 2, ujjainTextY + 25); 
    
    // English Title (Below Ujjain Text) - Reduced Margin
    const headerStart = ujjainTextY + 50; // Tight spacing
    ctx.font = '16px serif';
    ctx.fillStyle = '#4b5563'; 
    ctx.fillText('International Society for Krishna Consciousness', width / 2, headerStart);
    ctx.font = 'italic 14px serif';
    ctx.fillText('Founder Acharya: His Divine Grace A.C. Bhaktivedanta Swami Prabhupada', width / 2, headerStart + 20);
    
    // C. Corner Decoration
    const drawCorner = (x, y, rot) => {
      ctx.save();
      ctx.translate(x, y);
      ctx.rotate(rot);
      ctx.beginPath();
      ctx.arc(0, 0, 15, 0, Math.PI*1.5);
      ctx.strokeStyle = '#ca8a04';
      ctx.lineWidth = 3;
      ctx.stroke();
      ctx.restore();
    };
    drawCorner(55, 55, 0);
    drawCorner(width-55, 55, Math.PI/2);
    drawCorner(55, height-55, -Math.PI/2);
    drawCorner(width-55, height-55, Math.PI);


    // --- 5. Main Body Content ---
    const bodyStart = headerStart + 80;
    
    // Main Title
    ctx.font = 'bold 50px serif';
    ctx.fillStyle = '#ea580c'; // Saffron
    ctx.fillText('CERTIFICATE', width / 2, bodyStart);
    ctx.font = '24px serif';
    ctx.fillStyle = '#d97706';
    ctx.fillText('OF PARTICIPATION', width / 2, bodyStart + 35);

    // Line
    ctx.beginPath();
    ctx.moveTo(width/2 - 80, bodyStart + 50);
    ctx.lineTo(width/2 + 80, bodyStart + 50);
    ctx.strokeStyle = '#f59e0b';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Recipient Text
    ctx.font = 'italic 20px serif';
    ctx.fillStyle = '#4b5563';
    ctx.fillText('This is proudly presented to', width / 2, bodyStart + 90);

    // Name (Hero)
    ctx.font = 'bold italic 55px serif';
    ctx.fillStyle = '#1e3a8a'; // Deep Blue
    ctx.fillText(userName, width / 2, bodyStart + 150);
    
    // Decorative line under name
    const nameWidth = ctx.measureText(userName).width;
    ctx.beginPath();
    ctx.moveTo(width/2 - Math.max(100, nameWidth/2), bodyStart + 165);
    ctx.lineTo(width/2 + Math.max(100, nameWidth/2), bodyStart + 165);
    ctx.strokeStyle = '#93c5fd'; 
    ctx.lineWidth = 2;
    ctx.stroke();

    // Context
    ctx.font = '20px serif';
    ctx.fillStyle = '#374151';
    ctx.fillText('For successfully attending the three-day', width / 2, bodyStart + 210);
    ctx.fillText('Life Transformation Workshop', width / 2, bodyStart + 240);

    // Event Title Box
    const boxY = bodyStart + 280;
    ctx.fillStyle = '#fff7ed'; 
    ctx.strokeStyle = '#ea580c';
    ctx.lineWidth = 2;
    ctx.strokeRect(width/2 - 250, boxY, 500, 80);
    ctx.fillRect(width/2 - 248, boxY + 2, 496, 76);

    ctx.font = 'bold 40px sans-serif';
    ctx.fillStyle = '#c2410c'; // Rust
    ctx.fillText('PARIVARTAN CAMP', width / 2, boxY + 55);

    // Subtitle below box
    ctx.font = 'italic 18px serif';
    ctx.fillStyle = '#4b5563';
    ctx.fillText('"Based on the teachings of Bhagavad Gita"', width / 2, boxY + 110);

    // Date & Venue (Moved Down to avoid box)
    ctx.font = 'bold 20px sans-serif';
    ctx.fillStyle = '#9a3412';
    ctx.fillText('16 - 18 January', width / 2, boxY + 150);
    ctx.font = '18px sans-serif';
    ctx.fillText('ISKCON Ujjain Auditorium', width / 2, boxY + 180);

    // --- 6. Signature (Moved to safe area) ---
    const sigY = 980;
    
    // Line
    ctx.beginPath();
    ctx.moveTo(width / 2 - 100, sigY);
    ctx.lineTo(width / 2 + 100, sigY);
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;
    ctx.stroke();

    // Signature Text
    ctx.font = 'italic 28px cursive';
    ctx.fillStyle = '#1e40af';
    ctx.fillText('ISKCON Ujjain', width / 2, sigY - 15);

    // Label
    ctx.font = 'bold 16px sans-serif';
    ctx.fillStyle = '#1f2937';
    ctx.fillText('Authorized Signatory', width / 2, sigY + 25);

    // --- 7. Footer Quote ---
    ctx.font = 'bold 22px serif';
    ctx.fillStyle = '#ea580c';
    ctx.fillText('|| गीता के संग जीवन का रंग ||', width / 2, 1070);

  }, [userName, logoImage]);

  const downloadImage = () => {
    const canvas = canvasRef.current;
    const link = document.createElement('a');
    link.download = `Certificate_${userName.replace(/\s+/g, '_')}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div className="flex flex-col items-center gap-6">
      <div className="relative w-full max-w-[90vw] md:max-w-[500px] shadow-2xl border-8 border-white rounded-xl overflow-hidden bg-gray-50">
        <canvas 
          ref={canvasRef} 
          className="w-full h-auto block"
        />
      </div>
      
      <button 
        onClick={downloadImage}
        className="bg-gradient-to-r from-orange-600 to-amber-600 hover:from-orange-700 hover:to-amber-700 text-white font-bold py-3 px-10 rounded-full shadow-lg flex items-center gap-3 transform transition hover:scale-105"
      >
        <Download className="w-5 h-5" />
        Download Certificate
      </button>
    </div>
  );
};

export default App;